 TechnologyManager.instance.UnlockTech(burn.manaBurn.shieldTechnology,0);primary.SetMP(100);Hit(primary);Hit(primary);Check(AbsorbShield.IsActiveOn(caster),"Burn specialization creates absorb shield");caster.SetHP(500);caster.GetDamage(20,pure,foeOwner,primary,false,out _);Check(Mathf.Abs(caster.health-495)<.001f,"Two15 burns accumulate15 shield and absorb that amount");primary.SetMP(4);Hit(primary);caster.GetDamage(3,pure,foeOwner,primary,false,out _);Check(Mathf.Abs(caster.health-494)<.001f,"Partial4 mana adds exactly2 shield");primary.SetMP(0);Hit(primary);Check(!AbsorbShield.IsActiveOn(caster),"Empty mana does not refresh depleted shield");
 TechnologyManager.instance.LockTech(burn.manaBurn.shieldTechnology,0);primary.SetMP(100);Hit(primary);Check(!AbsorbShield.IsActiveOn(caster),"Locked shield technology stops future shield generation");var other=Spawn(center+Vector3.left*3,0,true);var c=(ChargeAttack)other.abilities.First(a=>a is ChargeAttack);c.Lock(other,0,0);primary.SetMP(20);Hit(primary);other.DealDamage(primary,1,physical,true,primary.transform.position);Check(primary.mana==0,"Two casters consume only remaining shared mana");other.Die(-1,null,false);primary.armor=0;}
 static void Warp(Unit u,Vector3 p){u.Hold();u.GetComponent<NavMeshAgent>().Warp(p);}
 static object State()=>((IDictionary)typeof(ChargeAttack).GetField("states",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(charge))[caster];
 static bool Active(){var s=State();return s!=null&&(bool)s.GetType().GetField("active").GetValue(s);}
 static float Cooldown(){var s=State();return s==null?0:(float)s.GetType().GetField("cooldownLeft").GetValue(s);}
 static void PrepareCharge(bool stun){caster.canAttack=false;caster.Hold();charge.Lock(caster,0,0);if(stun)TechnologyManager.instance.UnlockTech(charge.stunRequiredTech,0);Warp(caster,center);Warp(primary,center+Vector3.forward*6);primary.unitCategory=Unit.UnitCategory.Mage;primary.SetMP(100);primary.SetHP(1000);hits=0;observedStun=-1;charge.Unlock(caster,0,0);caster.OnAfterDamageDealCallbacks.RemoveAll(c=>c.Callback==Observe);caster.OnAfterDamageDealCallbacks.Add(new AfterDamageDealCallback{Callback=Observe});caster.canAttack=true;}
 static void Observe(Unit t,Vector3 pos,Effector[] e,float damage,bool direct,DamageType type,Unit source,Projectile proj,int owner,int level){if(direct&&source==caster){hits++;observedTarget=t;observedStun=t?t.stunTime:0;}}
 static void Capture(string name){var rt=new RenderTexture(1280,800,24);var prior=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var t=new Texture2D(1280,800,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,800),0,0);t.Apply();File.WriteAllBytes(W+name,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{camera.targetTexture=prior;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(rt);}}
